import React, { useRef, useState, useEffect } from "react";
import { File, FileJson, FileSpreadsheet } from "lucide-react";
import { useNavigate } from "react-router-dom";
import "../../styles/style.css";
import ActionList from "../../components/main/ActionList";
import AppHeader from "../../components/main/AppHeader";
import ChatInput from "../../components/main/ChatInput";
import ChatSidebar from "../../components/main/ChatSidebar";
import ChatWindow from "../../components/main/ChatWindow";
import DataPreviewModal from "../../components/main/DataPreviewModal";
import DatasetSidebar from "../../components/main/DatasetSidebar";
import HistoryModal from "../../components/main/HistoryModal";
import { sendChatMessage, deleteConversation, renameConversation } from "../../api/chat";
import { getAuthToken } from "../../api/auth";

export default function MainPage() {
  const [uploaded, setUploaded] = useState(false);
  const [datasetName, setDatasetName] = useState("");
  const [rows, setRows] = useState(0);
  const [columns, setColumns] = useState(0);
  const [uploadError, setUploadError] = useState("");
  const [tableData, setTableData] = useState([]);
  const [headers, setHeaders] = useState([]);
  const [showPreview, setShowPreview] = useState(false);
  const [selectedActions, setSelectedActions] = useState([]);
  const [inputValue, setInputValue] = useState("");

  const fileInputRef = useRef(null);
  const navigate = useNavigate();

  const actions = [
    "Handle Missing Values",
    "Remove Outliers",
    "Remove Duplicates",
    "Detect Feature Inconsistency",
    "Scale Data",
    "Encode Data",
    "Select Features",
  ];
  const [showHistory, setShowHistory] = useState(false);
  const [historyLogs, setHistoryLogs] = useState([]);
  // Toggle this to true to show a single demo operation when opening History.
  // Set to false when you want to rely only on the backend API.
  const USE_DEMO_HISTORY = true;

  // Backend integration state
  const [currentConversationId, setCurrentConversationId] = useState(null);
  const [isLoadingChat, setIsLoadingChat] = useState(false);
  const [chatError, setChatError] = useState("");

  // Check authentication on mount
  useEffect(() => {
    if (!getAuthToken()) {
      navigate("/login");
    }
  }, [navigate]);

  const [messages, setMessages] = useState([
    {
      sender: "bot",
      text: "Hello! I'm your AutoPrepAI assistant. Upload a dataset to get started.",
      time: new Date().toLocaleTimeString([], {
        hour: "2-digit",
        minute: "2-digit",
      }),
      list: [
        "Fix missing values",
        "Detect and handle outliers",
        "Detect and handle duplicates",
        "Resolve feature inconsistency",
        "Scale and encode data",
        "Feature selection",
      ],
    },
  ]);

  const [chats, setChats] = useState([
    {
      id: 1,
      title: "Chat 1",
      messages: [
        {
          sender: "bot",
          time: new Date().toLocaleTimeString([], {
            hour: "2-digit",
            minute: "2-digit",
          }),
          text: "Hello! I'm your AutoPrepAI assistant. Upload a dataset to get started.",
          list: [
            "Fix missing values",
            "Detect and handle outliers",
            "Detect and handle duplicates",
            "Resolve feature inconsistency",
            "Scale and encode data",
            "Feature selection",
          ],
        },
      ],
    },
  ]);

  const [activeChatId, setActiveChatId] = useState(1);
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);

  // Get current active chat
  const activeChat = chats.find((c) => c.id === activeChatId);

  const handleNewChat = () => {
    const newId = Date.now();
    const newChat = {
      id: newId,
      title: `Chat ${chats.length + 1}`,
      messages: [
        {
          sender: "bot",
          time: new Date().toLocaleTimeString([], {
            hour: "2-digit",
            minute: "2-digit",
          }),
          text: "Hello! Start a new conversation.",
        },
      ],
    };
    setChats((prev) => [...prev, newChat]);
    setActiveChatId(newId);
  };

  const handleRenameChat = async (chatId, title) => {
    const trimmedTitle = title.trim();
    if (!trimmedTitle) return;

    // Update local state first
    setChats((prev) =>
      prev.map((chat) =>
        chat.id === chatId ? { ...chat, title: trimmedTitle } : chat,
      ),
    );

    // If this chat has a conversation ID, update it on the backend
    const chat = chats.find((c) => c.id === chatId);
    if (chat && currentConversationId) {
      try {
        await renameConversation(currentConversationId, trimmedTitle);
      } catch (error) {
        console.error("Failed to rename conversation:", error);
        setChatError("Could not rename conversation");
      }
    }
  };

  const handleDeleteChat = async (chatId) => {
    // Remove from local state
    setChats((prev) => prev.filter((chat) => chat.id !== chatId));

    // If this is the active chat, switch to another
    if (activeChatId === chatId) {
      const remaining = chats.filter((c) => c.id !== chatId);
      if (remaining.length > 0) {
        setActiveChatId(remaining[0].id);
        setCurrentConversationId(null);
      } else {
        handleNewChat();
      }
    }

    // If this chat has a conversation ID, delete it from backend
    const chat = chats.find((c) => c.id === chatId);
    if (chat && currentConversationId) {
      try {
        await deleteConversation(currentConversationId);
      } catch (error) {
        console.error("Failed to delete conversation:", error);
        setChatError("Could not delete conversation");
      }
    }
  };

  const parseCSV = (text) => {
    const lines = text
      .replace(/\r\n/g, "\n")
      .trim()
      .split("\n")
      .filter(Boolean);
    if (lines.length === 0)
      return { rows: 0, columns: 0, data: [], headers: [] };
    const headers = lines[0].split(",");
    const data = lines.slice(1).map((line) => {
      const values = line.split(",");
      let obj = {};
      headers.forEach((h, i) => {
        obj[h] = values[i] || "";
      });
      return obj;
    });
    return { rows: data.length, columns: headers.length, data, headers };
  };

  const parseJSON = (text) => {
    const parsed = JSON.parse(text);
    const records = Array.isArray(parsed) ? parsed : [parsed];
    if (records.length === 0)
      return { rows: 0, columns: 0, data: [], headers: [] };
    const headers = Object.keys(records[0]);
    return {
      rows: records.length,
      columns: headers.length,
      data: records,
      headers,
    };
  };

  const handleUploadClick = () => fileInputRef.current?.click();

  const handleFileUpload = async (event) => {
    const selectedFile = event.target.files?.[0];
    if (!selectedFile) return;

    const fileName = selectedFile.name.toLowerCase();
    const isCSV = fileName.endsWith(".csv");
    const isJSON = fileName.endsWith(".json");

    if (!isCSV && !isJSON) {
      setUploadError("Please upload a CSV or JSON file.");
      event.target.value = "";
      return;
    }

    setIsLoadingChat(true);
    setChatError("");

    try {
      const text = await selectedFile.text();
      const parsed = isJSON ? parseJSON(text) : parseCSV(text);
      setDatasetName(selectedFile.name);
      setRows(parsed.rows);
      setColumns(parsed.columns);
      setTableData(parsed.data);
      setHeaders(parsed.headers);
      setUploadError("");
      setUploaded(true);

      // Send file to backend
      const response = await sendChatMessage({
        message: `I've uploaded a dataset: ${selectedFile.name}. It has ${parsed.rows} rows and ${parsed.columns} columns.`,
        mode: "chat",
        selectedIntents: [],
        conversationId: currentConversationId,
        dataset: selectedFile,
      });

      // Update conversation ID if this is a new conversation
      if (!currentConversationId && response.conversation_id) {
        setCurrentConversationId(response.conversation_id);
      }

      // Add bot acknowledgment
      const time = new Date().toLocaleTimeString([], {
        hour: "2-digit",
        minute: "2-digit",
      });

      const botMessage = {
        sender: "bot",
        text: response.response || `✓ Dataset loaded: ${selectedFile.name}`,
        time,
      };

      setChats((prev) =>
        prev.map((chat) =>
          chat.id === activeChatId
            ? { ...chat, messages: [...chat.messages, botMessage] }
            : chat,
        ),
      );
    } catch (error) {
      console.error("File upload error:", error);
      setChatError(error.message);
      setUploadError(error.message || "Could not upload file.");
    } finally {
      setIsLoadingChat(false);
    }

    event.target.value = "";
  };

  const handleReset = () => {
    setUploaded(false);
    setDatasetName("");
    setRows(0);
    setColumns(0);
    setTableData([]);
    setHeaders([]);
    setUploadError("");
    setSelectedActions([]);
  };

  // âœ… Download as CSV
  const handleDownload = () => {
    if (!tableData.length) return;
    const csvContent = [
      headers.join(","),
      ...tableData.map((row) => headers.map((h) => row[h]).join(",")),
    ].join("\n");
    const blob = new Blob([csvContent], { type: "text/csv" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `cleaned_${datasetName}`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const handleShowHistory = async () => {
    // Open modal
    setShowHistory(true);
    setChatError("");
    
    try {
      // If backend has a history endpoint, fetch logs from there
      // For now, we'll use the demo history
      if (!USE_DEMO_HISTORY) {
        const response = await fetch(
          `${process.env.REACT_APP_API_BASE_URL || "http://localhost:8022"}/conversations`,
          {
            headers: {
              Authorization: `Bearer ${getAuthToken()}`,
            },
          }
        );
        
        if (!response.ok) throw new Error(`HTTP ${response.status}`);
        const data = await response.json();
        setHistoryLogs(Array.isArray(data) ? data : []);
      }
    } catch (err) {
      console.error("Failed to fetch history logs:", err);
      setChatError("Could not load history");
      setHistoryLogs([]);
    }
  };
  const handleAutoClean = async () => {
    if (!tableData.length) {
      setChatError("No data to clean");
      return;
    }

    setChatError("");
    setIsLoadingChat(true);

    try {
      // Convert table data to CSV for backend
      const csvContent = [
        headers.join(","),
        ...tableData.map((row) => headers.map((h) => row[h]).join(",")),
      ].join("\n");

      const file = new File([csvContent], datasetName || "data.csv", {
        type: "text/csv",
      });

      const response = await sendChatMessage({
        message: "Please auto-clean this dataset with all recommended operations.",
        mode: "auto-clean",
        selectedIntents: selectedActions,
        conversationId: currentConversationId,
        dataset: file,
      });

      // Update conversation ID if this is a new conversation
      if (!currentConversationId && response.conversation_id) {
        setCurrentConversationId(response.conversation_id);
      }

      // The backend will return cleaned data
      if (response.cleaned_data) {
        // Parse cleaned data
        const cleaned = Array.isArray(response.cleaned_data)
          ? response.cleaned_data
          : [];
        setTableData(cleaned);

        const time = new Date().toLocaleTimeString([], {
          hour: "2-digit",
          minute: "2-digit",
        });

        setChats((prev) =>
          prev.map((chat) =>
            chat.id === activeChatId
              ? {
                  ...chat,
                  messages: [
                    ...chat.messages,
                    {
                      sender: "bot",
                      text: "✨ Your data has been automatically cleaned!",
                      time,
                    },
                  ],
                }
              : chat,
          ),
        );
      }
    } catch (error) {
      console.error(error);
      setChatError(error.message);
    } finally {
      setIsLoadingChat(false);
    }
  };

  // âœ… Send message
  const handleSend = async () => {
    if (!inputValue.trim()) return;

    const time = new Date().toLocaleTimeString([], {
      hour: "2-digit",
      minute: "2-digit",
    });
    const userMessage = { sender: "user", text: inputValue, time };

    // Add to active chat
    setChats((prev) =>
      prev.map((chat) =>
        chat.id === activeChatId
          ? { ...chat, messages: [...chat.messages, userMessage] }
          : chat,
      ),
    );
    
    const messageText = inputValue;
    setInputValue("");
    setChatError("");
    setIsLoadingChat(true);

    try {
      // Create dataset file if available
      let datasetFile = null;
      if (tableData.length > 0 && headers.length > 0) {
        const csvContent = [
          headers.join(","),
          ...tableData.map((row) => headers.map((h) => row[h]).join(",")),
        ].join("\n");
        datasetFile = new File([csvContent], datasetName || "data.csv", {
          type: "text/csv",
        });
      }

      // Send to backend
      const response = await sendChatMessage({
        message: messageText,
        mode: "chat",
        selectedIntents: selectedActions,
        conversationId: currentConversationId,
        dataset: datasetFile,
      });

      // Update conversation ID if this is a new conversation
      if (!currentConversationId && response.conversation_id) {
        setCurrentConversationId(response.conversation_id);
      }

      // Add bot response
      const botTime = new Date().toLocaleTimeString([], {
        hour: "2-digit",
        minute: "2-digit",
      });
      const botMessage = {
        sender: "bot",
        text: response.response || "I received your message!",
        time: botTime,
      };

      setChats((prev) =>
        prev.map((chat) =>
          chat.id === activeChatId
            ? { ...chat, messages: [...chat.messages, botMessage] }
            : chat,
        ),
      );
    } catch (error) {
      console.error("Chat error:", error);
      setChatError(error.message);
      
      const botTime = new Date().toLocaleTimeString([], {
        hour: "2-digit",
        minute: "2-digit",
      });
      const errorMessage = {
        sender: "bot",
        text: `Error: ${error.message}`,
        time: botTime,
      };

      setChats((prev) =>
        prev.map((chat) =>
          chat.id === activeChatId
            ? { ...chat, messages: [...chat.messages, errorMessage] }
            : chat,
        ),
      );
    } finally {
      setIsLoadingChat(false);
    }
  };


  const chatEndRef = useRef(null);

  // Auto scroll when messages change
  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  const toggleAction = (action) => {
    setSelectedActions((prev) =>
      prev.includes(action)
        ? prev.filter((a) => a !== action)
        : [...prev, action],
    );
  };

  const handleActionClick = async (action) => {
    // Toggle the action
    const newSelectedActions = selectedActions.includes(action)
      ? selectedActions.filter((a) => a !== action)
      : [...selectedActions, action];
    
    setSelectedActions(newSelectedActions);

    // If dataset is uploaded and we're adding (not removing) this action, send a message
    if (!selectedActions.includes(action) && tableData.length > 0 && headers.length > 0) {
      setChatError("");
      setIsLoadingChat(true);

      try {
        // Create dataset file
        const csvContent = [
          headers.join(","),
          ...tableData.map((row) => headers.map((h) => row[h]).join(",")),
        ].join("\n");
        const datasetFile = new File([csvContent], datasetName || "data.csv", {
          type: "text/csv",
        });

        // Add user message to chat
        const time = new Date().toLocaleTimeString([], {
          hour: "2-digit",
          minute: "2-digit",
        });
        const userMessage = { sender: "user", text: `Please ${action}`, time };
        
        setChats((prev) =>
          prev.map((chat) =>
            chat.id === activeChatId
              ? { ...chat, messages: [...chat.messages, userMessage] }
              : chat,
          ),
        );

        // Send to backend
        const response = await sendChatMessage({
          message: `Please ${action.toLowerCase()}`,
          mode: "chat",
          selectedIntents: [action],
          conversationId: currentConversationId,
          dataset: datasetFile,
        });

        // Update conversation ID if this is a new conversation
        if (!currentConversationId && response.conversation_id) {
          setCurrentConversationId(response.conversation_id);
        }

        // Add bot response
        const botTime = new Date().toLocaleTimeString([], {
          hour: "2-digit",
          minute: "2-digit",
        });
        const botMessage = {
          sender: "bot",
          text: response.response || `Processing: ${action}`,
          time: botTime,
        };

        setChats((prev) =>
          prev.map((chat) =>
            chat.id === activeChatId
              ? { ...chat, messages: [...chat.messages, botMessage] }
              : chat,
          ),
        );

        // Update table with processed data if available
        if (response.cleaned_data && Array.isArray(response.cleaned_data)) {
          setTableData(response.cleaned_data);
        }
      } catch (error) {
        console.error("Action error:", error);
        setChatError(error.message);
        
        const botTime = new Date().toLocaleTimeString([], {
          hour: "2-digit",
          minute: "2-digit",
        });
        const errorMessage = {
          sender: "bot",
          text: `Error: ${error.message}`,
          time: botTime,
        };

        setChats((prev) =>
          prev.map((chat) =>
            chat.id === activeChatId
              ? { ...chat, messages: [...chat.messages, errorMessage] }
              : chat,
          ),
        );
      } finally {
        setIsLoadingChat(false);
      }
    }
  };

  const getFileIcon = (name) => {
    if (name.endsWith(".json")) return FileJson;
    if (name.endsWith(".csv")) return FileSpreadsheet;
    return File;
  };

  const DatasetIcon = getFileIcon(datasetName);

  return (
    <div className="container">
      <ChatSidebar
        sidebarCollapsed={sidebarCollapsed}
        setSidebarCollapsed={setSidebarCollapsed}
        handleNewChat={handleNewChat}
        chats={chats}
        activeChatId={activeChatId}
        setActiveChatId={setActiveChatId}
        handleRenameChat={handleRenameChat}
        handleDeleteChat={handleDeleteChat}
      />

      <DatasetSidebar
        fileInputRef={fileInputRef}
        handleFileUpload={handleFileUpload}
        uploaded={uploaded}
        handleUploadClick={handleUploadClick}
        uploadError={uploadError}
        DatasetIcon={DatasetIcon}
        datasetName={datasetName}
        rows={rows}
        columns={columns}
        setShowPreview={setShowPreview}
        handleDownload={handleDownload}
        handleShowHistory={handleShowHistory}
        handleReset={handleReset}
        handleAutoClean={handleAutoClean}
      />

      <div className="main">
        <AppHeader onLoginClick={() => navigate("/login")} />
        <ChatWindow activeChat={activeChat} chatEndRef={chatEndRef} />
        <ActionList
          actions={actions}
          uploaded={uploaded}
          selectedActions={selectedActions}
          toggleAction={toggleAction}
          onActionClick={handleActionClick}
        />
        <ChatInput
          inputValue={inputValue}
          setInputValue={setInputValue}
          handleSend={handleSend}
        />
      </div>

      {showPreview && (
        <DataPreviewModal
          onClose={() => setShowPreview(false)}
          data={tableData}
          headers={headers}
          datasetName={datasetName}
        />
      )}
      {showHistory && (
        <HistoryModal
          onClose={() => setShowHistory(false)}
          logs={historyLogs}
        />
      )}
    </div>
  );
}
